sysauto_script.script:
var escalationHours = 4;

var escalationOrder = {
    'Mess Staff Group': 'Hostel Admin Group',
    'Hostel Admin Group': 'Hostel Management Group'
};

var task = new GlideRecord('x_snc_campus_foo_1_problem_task');
task.addQuery('state', 'NOT IN', '3,4');
task.query();

while (task.next()) {
    var hoursOpen = gs.dateDiff(task.opened_at, gs.nowDateTime(), true) / 3600;

    if (hoursOpen >= escalationHours) {
        var currentGroupName = task.assignment_group.name.toString();
        var nextGroupName = escalationOrder[currentGroupName];

        if (nextGroupName) {
            var nextGroup = new GlideRecord('sys_user_group');
            nextGroup.addQuery('name', nextGroupName);
            nextGroup.query();

            if (nextGroup.next()) {
                task.assignment_group = nextGroup.getUniqueValue();
                task.opened_at = new GlideDateTime();
                task.update();
                gs.info('Escalated ' + task.number + ' to ' + nextGroupName);
            }
        }
    }
}
